-- Daily arecanut arrivals (docs/DAILY_ARRIVALS.md). Additive only: no existing table, row or trigger is changed.
--  - krama_arrivals: KRAMA Commoditywise Daily Report (Department of Agricultural Marketing, Government of Karnataka),
--    public, no login; the unattended daily source.
--  - agmarknet_v2_daily: AGMARKNET 2.0 date-wise report, fetched in an operator's logged-in session; secondary source.
-- Rows never feed market_price_observations, the reference index or market_arrivals.
--
-- Each document is a complete snapshot of the date(s) it covers. The current rows for a date are those of the latest
-- reported document for that source and date, so corrections and removed rows need no update or delete.
--
-- Rollback (nothing else references these objects):
--   DROP VIEW market_arrival_days_current; DROP TABLE market_arrival_days; DROP TABLE arrival_daily_documents;
--   DROP TABLE arrival_market_aliases;
--   DELETE FROM source_ingestion_runs WHERE source_id IN ('source-krama-arrivals', 'source-agmarknet-v2-daily');
--   DELETE FROM data_sources WHERE id IN ('source-krama-arrivals', 'source-agmarknet-v2-daily');
INSERT OR IGNORE INTO data_sources (id, source_key, name, source_type) VALUES
  ('source-krama-arrivals', 'krama_arrivals', 'KRAMA daily arrivals (Department of Agricultural Marketing, Karnataka)', 'public_report'),
  ('source-agmarknet-v2-daily', 'agmarknet_v2_daily', 'AGMARKNET 2.0 date-wise daily arrivals', 'public_report');

CREATE TABLE arrival_daily_documents (
  id TEXT PRIMARY KEY,
  source_key TEXT NOT NULL CHECK (source_key IN ('krama_arrivals', 'agmarknet_v2_daily')),
  request_url TEXT NOT NULL,
  request_params TEXT NOT NULL,
  period_start TEXT NOT NULL CHECK (period_start GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  period_end TEXT NOT NULL CHECK (period_end GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  status TEXT NOT NULL CHECK (status IN ('reported', 'not_reported')),
  row_count INTEGER NOT NULL CHECK (row_count >= 0),
  raw_sha256 TEXT NOT NULL CHECK (length(raw_sha256) = 64),
  raw_bytes INTEGER NOT NULL CHECK (raw_bytes > 0),
  payload_format TEXT NOT NULL CHECK (payload_format IN ('krama_commodity_table/1', 'agmarknet_datewise_json/1')),
  payload TEXT NOT NULL,
  payload_sha256 TEXT NOT NULL CHECK (length(payload_sha256) = 64),
  parser_version TEXT NOT NULL,
  fetched_at TEXT NOT NULL,
  imported_at TEXT NOT NULL,
  CHECK (period_start <= period_end),
  -- One date, or one whole calendar month: the current view finds a date's documents by these two keys alone.
  CHECK (period_start = period_end OR (substr(period_start, 9, 2) = '01' AND period_end = date(period_start, '+1 month', '-1 day'))),
  UNIQUE (source_key, request_url, payload_sha256)
);
CREATE INDEX arrival_daily_documents_period ON arrival_daily_documents(source_key, period_start, period_end, status, fetched_at);
CREATE TRIGGER arrival_daily_documents_no_update BEFORE UPDATE ON arrival_daily_documents
BEGIN SELECT RAISE(ABORT, 'daily arrival documents are immutable'); END;
CREATE TRIGGER arrival_daily_documents_no_delete BEFORE DELETE ON arrival_daily_documents
BEGIN SELECT RAISE(ABORT, 'daily arrival documents are immutable'); END;

-- One row per market, date, variety and grade in a document, as published (quantity in its own unit, plus tonnes).
CREATE TABLE market_arrival_days (
  id TEXT PRIMARY KEY,
  document_id TEXT NOT NULL REFERENCES arrival_daily_documents(id),
  source_key TEXT NOT NULL CHECK (source_key IN ('krama_arrivals', 'agmarknet_v2_daily')),
  commodity_code TEXT NOT NULL DEFAULT 'arecanut',
  state TEXT NOT NULL,
  source_market_name TEXT NOT NULL,
  observation_date TEXT NOT NULL CHECK (observation_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  variety TEXT NOT NULL,
  grade TEXT,
  quantity_original REAL NOT NULL CHECK (quantity_original >= 0),
  unit_original TEXT NOT NULL,
  quantity_tonnes REAL CHECK (quantity_tonnes IS NULL OR quantity_tonnes >= 0),
  unit_status TEXT NOT NULL CHECK (unit_status IN ('converted', 'unknown_unit')),
  minimum_price REAL CHECK (minimum_price IS NULL OR minimum_price >= 0),
  maximum_price REAL CHECK (maximum_price IS NULL OR maximum_price >= 0),
  modal_price REAL CHECK (modal_price IS NULL OR modal_price >= 0),
  price_unit TEXT CHECK (price_unit IS NULL OR price_unit = 'INR/quintal'),
  CHECK ((unit_status = 'converted') = (quantity_tonnes IS NOT NULL))
);
CREATE UNIQUE INDEX market_arrival_days_identity
  ON market_arrival_days(document_id, source_market_name, observation_date, variety, COALESCE(grade, ''));
CREATE INDEX market_arrival_days_scope ON market_arrival_days(commodity_code, state, observation_date, source_key);
CREATE TRIGGER market_arrival_days_no_update BEFORE UPDATE ON market_arrival_days
BEGIN SELECT RAISE(ABORT, 'daily arrival rows are append-only'); END;
CREATE TRIGGER market_arrival_days_no_delete BEFORE DELETE ON market_arrival_days
BEGIN SELECT RAISE(ABORT, 'daily arrival rows are append-only'); END;

-- Source market names mapped to the AGMARKNET market name (as used by the price pages) and its district.
-- Insert-only: a correction is a new version, and the highest version applies.
CREATE TABLE arrival_market_aliases (
  source_key TEXT NOT NULL CHECK (source_key IN ('krama_arrivals', 'agmarknet_v2_daily')),
  source_market_name TEXT NOT NULL,
  district TEXT NOT NULL,
  market TEXT NOT NULL,
  mapping_status TEXT NOT NULL CHECK (mapping_status IN ('verified', 'inferred')),
  evidence TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
  created_at TEXT NOT NULL,
  PRIMARY KEY (source_key, source_market_name, version)
);
CREATE TRIGGER arrival_market_aliases_no_update BEFORE UPDATE ON arrival_market_aliases
BEGIN SELECT RAISE(ABORT, 'market aliases are versioned; insert a new version'); END;
CREATE TRIGGER arrival_market_aliases_no_delete BEFORE DELETE ON arrival_market_aliases
BEGIN SELECT RAISE(ABORT, 'market aliases are versioned; insert a new version'); END;
-- KRAMA names: matched to the AGMARKNET market master by spelling and, where "verified", by identical same-day arrivals and
-- modal prices in a sample of 14 dates (2021-2026). AGMARKNET names: districts from its public market master.

-- The rows of the latest reported document for each source and date, with mapped market and district names.
CREATE VIEW market_arrival_days_current AS
SELECT r.id, r.document_id, r.source_key, r.commodity_code, r.state, r.source_market_name,
  COALESCE(a.market, r.source_market_name) AS market, a.district AS district,
  CASE WHEN a.market IS NULL THEN 'unmapped' ELSE a.mapping_status END AS mapping_status,
  r.observation_date, r.variety, r.grade, r.quantity_original, r.unit_original, r.quantity_tonnes, r.unit_status,
  r.minimum_price, r.maximum_price, r.modal_price, r.price_unit, d.fetched_at, d.imported_at, d.request_url
FROM market_arrival_days r
JOIN arrival_daily_documents d ON d.id = r.document_id
LEFT JOIN arrival_market_aliases a ON a.source_key = r.source_key AND a.source_market_name = r.source_market_name
  AND a.version = (SELECT MAX(x.version) FROM arrival_market_aliases x WHERE x.source_key = a.source_key AND x.source_market_name = a.source_market_name)
-- Two index probes per row (the date itself, or the first of its month), not a scan of every earlier document.
WHERE d.id = (SELECT d2.id FROM arrival_daily_documents d2 WHERE d2.source_key = r.source_key AND d2.status = 'reported'
  AND d2.period_start IN (r.observation_date, substr(r.observation_date, 1, 8) || '01') AND d2.period_end >= r.observation_date
  ORDER BY d2.fetched_at DESC, d2.imported_at DESC, d2.id DESC LIMIT 1);
